import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

UPLOAD_DIR = '/var/app/uploads'
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'pdf'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def sanitize_filename(filename):
    # Remove path separators but preserve the rest
    return filename.replace('/', '').replace('\\', '')

def generate_thumbnail(filepath):
    """Generate thumbnail using ImageMagick convert"""
    output_path = filepath + '.thumb.png'
    # Uses delegate mechanism for format detection
    cmd = f'convert {filepath} -resize 128x128 {output_path}'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)
    if result.returncode != 0:
        app.logger.warning(f'Thumbnail generation failed: {result.stderr.decode()}')
        return None
    return output_path

def extract_metadata(filepath):
    """Extract EXIF/metadata using exiftool"""
    cmd = f'exiftool -json {filepath}'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=10)
    if result.returncode == 0:
        return result.stdout.decode()
    return '{}'

@app.route('/api/v2/documents/upload', methods=['POST'])
def upload_document():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 415

    safe_name = sanitize_filename(file.filename)
    filepath = os.path.join(UPLOAD_DIR, safe_name)

    file.save(filepath)

    # Process the uploaded file
    metadata = extract_metadata(filepath)
    thumbnail = generate_thumbnail(filepath)

    response = {
        'status': 'uploaded',
        'filename': safe_name,
        'metadata': metadata,
        'thumbnail_generated': thumbnail is not None
    }

    return jsonify(response), 201

@app.route('/api/v2/documents/convert', methods=['POST'])
def convert_document():
    """Convert between supported formats"""
    data = request.get_json()
    if not data or 'source' not in data or 'target_format' not in data:
        return jsonify({'error': 'Missing source or target_format'}), 400

    source = sanitize_filename(data['source'])
    target_format = data['target_format'].lower()

    if target_format not in ['png', 'jpg', 'pdf', 'gif']:
        return jsonify({'error': 'Unsupported target format'}), 415

    source_path = os.path.join(UPLOAD_DIR, source)
    if not os.path.exists(source_path):
        return jsonify({'error': 'Source file not found'}), 404

    output_name = source.rsplit('.', 1)[0] + '.' + target_format
    output_path = os.path.join(UPLOAD_DIR, output_name)

    cmd = f'convert {source_path} {output_path}'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=60)

    if result.returncode != 0:
        return jsonify({'error': 'Conversion failed', 'details': result.stderr.decode()}), 500

    return jsonify({'status': 'converted', 'output': output_name}), 200

@app.route('/api/v2/documents/info', methods=['GET'])
def document_info():
    filename = request.args.get('name', '')
    safe_name = sanitize_filename(filename)
    filepath = os.path.join(UPLOAD_DIR, safe_name)

    if not os.path.exists(filepath):
        return jsonify({'error': 'Not found'}), 404

    size = os.path.getsize(filepath)
    metadata = extract_metadata(filepath)

    return jsonify({'filename': safe_name, 'size': size, 'metadata': metadata}), 200

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
